/**
 * =============================================================================
 * VERIFY PAGE - Main landing page for document verification
 * =============================================================================
 */

import { useState, useCallback, useRef, useEffect } from 'react';
// KS-528: was react-router-dom (v6), now react-router 7. v6.30.6 already exported these from react-router except BrowserRouter and useSearchParams; only the module name changed.
import { useNavigate } from 'react-router';
import { motion } from 'motion/react';
import {
  Upload,
  Search,
  ScanLine,
  Menu as MenuIcon,
  Home,
  Globe,
  Shield,
} from 'lucide-react';
import { useDropzone } from 'react-dropzone';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import { Alert, AlertDescription } from '@/components/ui/alert';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import QrScanner from './QrScanner';
import { ThemeToggle } from './ui/theme-toggle';
import { safeFetch } from '@shared/api';
import { VerifyResponseSchema } from '@shared/schemas/verify';

const API_URL = import.meta.env.VITE_API_URL || '/api';

function failureMessage(kind: 'network' | 'http' | 'json' | 'shape'): string {
  switch (kind) {
    case 'network':
      return 'Could not reach the verification service. Please check your connection and try again.';
    case 'http':
      return 'The verification service returned an error. Please try again.';
    case 'json':
      return 'The server returned an unreadable response. Please try again.';
    case 'shape':
      return 'The verification service returned an unexpected response. This is likely a bug — please report it.';
  }
}

export default function VerifyPage() {
  const navigate = useNavigate();
  const [tab, setTab] = useState('upload');
  const [documentId, setDocumentId] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  // Close menu on outside click
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setMenuOpen(false);
      }
    };
    if (menuOpen) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [menuOpen]);

  const handleVerifyById = async () => {
    if (!documentId.trim()) {
      setError('Please enter a document ID');
      return;
    }
    setLoading(true);
    setError(null);
    const id = documentId.trim();
    const r = await safeFetch(
      `${API_URL}/verification/verify`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ documentId: id }),
      },
      VerifyResponseSchema,
    );
    setLoading(false);
    if (r.ok) {
      navigate(`/result/${id}`, { state: { result: r.data } });
      return;
    }
    // Validated failure — surface the right message rather than silently
    // navigating to a "no result" page.
    setError(failureMessage(r.kind));
  };

  const hashFile = async (file: File): Promise<string> => {
    const buffer = await file.arrayBuffer();
    const hashBuffer = await crypto.subtle.digest('SHA-256', buffer);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return `sha256:${hashArray.map(b => b.toString(16).padStart(2, '0')).join('')}`;
  };

  const onDrop = useCallback(async (acceptedFiles: File[]) => {
    if (acceptedFiles.length === 0) return;

    setLoading(true);
    setError(null);

    let file: File;
    let contentHash: string;
    try {
      file = acceptedFiles[0];
      contentHash = await hashFile(file);
    } catch {
      setLoading(false);
      setError('Failed to read the uploaded file. Please try again.');
      return;
    }

    const r = await safeFetch(
      `${API_URL}/verification/verify`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ contentHash, fileName: file.name }),
      },
      VerifyResponseSchema,
    );
    setLoading(false);

    if (!r.ok) {
      setError(failureMessage(r.kind));
      return;
    }

    const data = { ...r.data, fileName: file.name };
    if (data.verified === true) {
      navigate('/result', { state: { result: data } });
    } else if (data.documentId) {
      navigate(`/result/${data.documentId}`, { state: { result: data } });
    } else {
      navigate('/result', { state: { result: data } });
    }
  }, [navigate]);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    maxFiles: 1,
    maxSize: 50 * 1024 * 1024,
  });

  return (
    <div className="min-h-screen flex flex-col bg-background">
      {/* Header */}
      <header
        data-testid="verifier-header"
        className="py-4 px-6 flex justify-between items-center"
      >
        <div className="flex items-center gap-3">
          <img src={`${import.meta.env.BASE_URL}assets/secuura-swan.svg`} alt="Secuura" className="w-8 h-8 hidden dark:block" />
          <img src={`${import.meta.env.BASE_URL}assets/secuura-wordmark.svg`} alt="Secuura" className="h-4 hidden dark:block" />
          <img src={`${import.meta.env.BASE_URL}assets/secuura-lockup-dark.png`} alt="Secuura" className="h-8 dark:hidden" />
        </div>

        <div className="flex items-center gap-2">
          <ThemeToggle />
          <div className="relative" ref={menuRef}>
            <button
              onClick={() => setMenuOpen(!menuOpen)}
              data-testid="verifier-menu-btn"
              aria-label="Open menu"
              aria-expanded={menuOpen}
              aria-haspopup="menu"
              className="p-2 rounded-lg text-muted-foreground hover:text-foreground transition-colors"
            >
              <MenuIcon className="w-5 h-5" />
            </button>

          {menuOpen && (
            <div className="absolute right-0 mt-2 w-52 rounded-xl bg-card border border-primary/10 shadow-xl z-50">
              <button
                className="w-full flex items-center gap-3 px-4 py-3 text-sm text-foreground hover:bg-primary/5 rounded-t-xl transition-colors"
                onClick={() => { setMenuOpen(false); navigate('/'); }}
              >
                <Home className="w-4 h-4 text-muted-foreground" />
                Verify Document
              </button>
              <a
                href="/website/"
                className="flex items-center gap-3 px-4 py-3 text-sm text-foreground hover:bg-primary/5 transition-colors"
                onClick={() => setMenuOpen(false)}
              >
                <Globe className="w-4 h-4 text-muted-foreground" />
                Secuura Website
              </a>
              <div className="border-t border-primary/10" />
              <a
                href="/admin/"
                className="flex items-center gap-3 px-4 py-3 text-sm text-foreground hover:bg-primary/5 rounded-b-xl transition-colors"
                onClick={() => setMenuOpen(false)}
              >
                <Shield className="w-4 h-4 text-muted-foreground" />
                Admin Portal
              </a>
            </div>
            )}
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 flex items-center justify-center px-4 py-8">
        <div className="w-full max-w-2xl">
          {/* Hero Text */}
          {/* H30 / H16 (2026-04-28): the headline used to fade in from
              opacity 0. Browser tests + accessibility scanners that
              snapshot mid-animation read the half-transparent heading
              as a contrast failure (the actual computed contrast is
              ~16:1 in dark mode, well above WCAG AAA). Drop the
              opacity animation; keep the y-slide for the entrance
              feel. Renders at full contrast from frame 0. */}
          <motion.div
            className="text-center mb-12"
            initial={{ y: 20 }}
            animate={{ y: 0 }}
            transition={{ duration: 0.5 }}
          >
            <h1 className="text-4xl md:text-5xl font-bold mb-4 tracking-tight text-foreground">
              Document Verification
            </h1>
            <p className="text-lg text-muted-foreground max-w-xl mx-auto font-light leading-relaxed">
              Verify any certified document against its blockchain-anchored certification record with cryptographic proof.
            </p>
          </motion.div>

          {/* Verification Card */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.1 }}
          >
            <Card className="bg-card/80 backdrop-blur-xl border-primary/15">
              <CardContent className="p-6">
                {/* H23 (2026-04-28): wrap with delayDuration=400 so the
                    tooltip doesn't pop on a single click — the previous
                    USER SIMULATED TEST run misread the tab tooltip
                    floating over the panel as "no input rendered" because
                    the tooltip default-positions BELOW the trigger and
                    overlays the panel content for the active tab. The
                    delay also forces an actual hover gesture rather than
                    a tap-induced flash. Each TooltipContent below now
                    also pins side="top" to put the tooltip above the
                    tab list rather than over the panel below. */}
                <TooltipProvider delayDuration={400}>
                  <Tabs
                    value={tab}
                    onValueChange={(v) => { setTab(v); setError(null); }}
                    data-testid="verify-tabs"
                  >
                    <TabsList className="grid w-full grid-cols-3 mb-6 bg-muted/30">
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <TabsTrigger value="upload" data-testid="tab-upload" className="gap-2">
                            <Upload className="w-4 h-4" />
                            <span className="hidden sm:inline">Upload File</span>
                          </TabsTrigger>
                        </TooltipTrigger>
                        <TooltipContent side="top">
                          Upload a document to verify its authenticity against its blockchain-anchored certification record
                        </TooltipContent>
                      </Tooltip>
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <TabsTrigger value="id" data-testid="tab-id" className="gap-2">
                            <Search className="w-4 h-4" />
                            <span className="hidden sm:inline">Enter ID</span>
                          </TabsTrigger>
                        </TooltipTrigger>
                        <TooltipContent side="top">
                          Enter a document ID or certification reference to look up its verification status
                        </TooltipContent>
                      </Tooltip>
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <TabsTrigger value="qr" data-testid="tab-qr" className="gap-2">
                            <ScanLine className="w-4 h-4" />
                            <span className="hidden sm:inline">Scan QR</span>
                          </TabsTrigger>
                        </TooltipTrigger>
                        <TooltipContent side="top">
                          Scan a QR code printed on or attached to a certified document for instant verification
                        </TooltipContent>
                      </Tooltip>
                    </TabsList>

                    {error && (
                      <Alert variant="destructive" className="mb-4" data-testid="verify-error">
                        <AlertDescription>{error}</AlertDescription>
                      </Alert>
                    )}

