/**
 * =============================================================================
 * KS-1564 — the Admin Dashboard API Keys page never invents an organisation id
 * =============================================================================
 * The page used to list and mint with a hard-coded, non-uuid organisation id
 * (the placeholder is built from two pieces below so this file does not carry
 * the literal itself). It worked, so nothing noticed: it is the SOURCE of
 * non-canonical `svc_api_keys.organization_id` rows, and it would have broken
 * the moment the security service refused an id that is not a real organisation
 * (KS-1570's per-admin scope, KS-1553's uuid enforcement).
 *
 * This is a SOURCE guard, stated as such: frontend/admin has no unit-test
 * framework, so what it pins is the wiring in the text, NOT the browser
 * behaviour. The behaviour is covered by the Playwright cells added to
 * tests/e2e/tests/sysadmin-exhaustive.admin.spec.ts, which need the local stack.
 *
 * KS-1589 item A — WHY THIS READS THE AST AND NOT A REGEX.
 * The first version of this guard scraped the source with regular expressions, and
 * the pull request 1537 round-2 gate showed five mutants walking straight past it
 * while all nine cells stayed green:
 *
 *   N3   the race-guard line turned into a COMMENT — a text-position check cannot
 *        tell a live statement from a commented-out one;
 *   N6b  `fetchApiKeys(String(orgId) || [...].join('-'))` alongside a plain call —
 *        the argument pattern was `[^()]*`, so an argument CONTAINING parentheses
 *        was not matched and the call was simply skipped;
 *   N7   an alias call, `const f = fetchApiKeys; f('x')` — no parenthesis follows
 *        the name, so the scrape never saw it;
 *   N9   the organisations-loader sequence guard deleted — no cell pinned it;
 *   N10  the Generate in-flight guard (`submitRef`) deleted — no cell pinned it.
 *
 * N3 is the KS-1319 class recurring in a second guard ("the wiring pin passes on a
 * commented-out line"), which is the argument for parsing rather than for a third
 * regex. So the detectors below are built on the TypeScript AST: a comment is not a
 * node, an argument is a node whatever it contains, and a name used as a VALUE is
 * distinguishable from a name that is called. `ks781-p3-3-body-parser-order.test.ts`
 * in this same package uses the compiler API the same way.
 *
 * Seven cells and four controls:
 *   0.  the admin source tree exists (the guard is looking at something);
 *   0b. with no harness override, that tree is the one in this checkout;
 *   1.  no placeholder literal anywhere under frontend/admin/src;
 *   2.  fetchApiKeys takes a REQUIRED organisation id (no `?`, no fallback);
 *   3.  the createApiKey call site passes an identifier, never a string literal;
 *   4.  NO fetchApiKeys CALL passes anything but a plain identifier (so `x || 'y'`,
 *       `x ?? 'y'`, a quote, a template, a ternary or `String(x) || …` is refused),
 *       and the name is never taken as a VALUE — an alias defeats cell 4 by moving
 *       the call site to a different name (the gate's Minor 5, plus N6b and N7);
 *   5.  loadKeys is wired latest-request-wins: a sequence number is taken, then the
 *       await, then the comparison, and the comparison comes before the FIRST state
 *       write that follows the await (the gate's Major 1, plus N3);
 *   6.  loadOrganizations is wired the same way (N9);
 *   7.  Generate is guarded against a double submit by a synchronous in-flight ref,
 *       checked and set before the await and cleared after it (N10);
 *   C1. the walker finds a literal that is known to be in the tree;
 *   C2. the mint call-site extractor reports a literal when fed one (a planted
 *       mutant), and an identifier when fed the real shape, so cell 3 can fail;
 *   C3. the argument checker, the alias checker and the race-wiring checker each
 *       REFUSE a planted bad shape;
 *   C4. a bad call quoted inside a COMMENT is not a finding, and a commented-out
 *       guard line is not a guard — the two halves of reading the AST.
 *
 * WHAT THESE CANNOT PIN. Cells 5, 6 and 7 pin that the guard statements exist and
 * stand in the right ORDER; they cannot show that a stale answer is really dropped
 * in a browser, or that a second click really mints nothing. Only a browser run
 * pins that behaviour; the recipe is in the pull request body (the gate's own
 * reproduction). A literal can still be hidden by building it from pieces in a
 * variable that is then passed by name; cells 3 and 4 refuse expressions at the
 * call sites, not the provenance of a variable.
 * =============================================================================
 */

import { describe, it, expect } from 'vitest';
import { readFileSync, existsSync, readdirSync } from 'node:fs';
import { join, resolve, relative } from 'node:path';
import ts from 'typescript';

function findDevRoot(start: string): string {
  let dir = start;
  for (let i = 0; i < 10; i++) {
    if (existsSync(join(dir, 'services')) && existsSync(join(dir, 'packages')) && existsSync(join(dir, 'frontend'))) return dir;
    const parent = resolve(dir, '..');
    if (parent === dir) break;
    dir = parent;
  }
  throw new Error(`[ks1564 guard] could not locate the Dev root from ${start}`);
}

const DEV_ROOT = findDevRoot(process.cwd());

/**
 * The admin source tree these cells read.
 *
 * `KS1564_ADMIN_SRC` exists so a mutant harness can point the guard at a COPY of the tree and show
 * that a deliberate break turns a named cell RED. It is a harness affordance and nothing else: the
 * product file is never edited to prove a guard works. Cell 0b asserts that with the variable unset
 * the tree really is the one in this checkout, so the override cannot quietly become the default.
 */
const ADMIN_SRC = process.env.KS1564_ADMIN_SRC ?? join(DEV_ROOT, 'frontend', 'admin', 'src');
const API_TS = join(ADMIN_SRC, 'services', 'api.ts');
const PAGE_TSX = join(ADMIN_SRC, 'pages', 'ApiKeys.tsx');

/** The retired placeholder, assembled so this file never contains it whole. */
const PLACEHOLDER = ['default', 'org'].join('-');

function walk(dir: string, out: string[] = []): string[] {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === 'node_modules' || entry.name === 'dist') continue;
    const full = join(dir, entry.name);
    if (entry.isDirectory()) walk(full, out);
    else if (/\.(ts|tsx)$/.test(entry.name)) out.push(full);
  }
  return out;
}

/** Files under the admin source that contain the text, as repo-relative paths. */
function filesContaining(text: string): string[] {
  return walk(ADMIN_SRC)
    .filter((f) => readFileSync(f, 'utf8').includes(text))
    .map((f) => relative(DEV_ROOT, f));
}

/**
 * Parse a source string.
 *
 * The file name drives the script kind, so the `.tsx` page parses its JSX instead of reading `<` as
 * a comparison; `setParentNodes` is on because every predicate below asks a node about its parent.
 *
 * @param {string} source - The source text.
 * @param {string} fileName - A name whose extension picks TS or TSX.
 * @returns {ts.SourceFile} The parsed file.
 */
function parse(source: string, fileName: string): ts.SourceFile {
  const kind = fileName.endsWith('.tsx') ? ts.ScriptKind.TSX : ts.ScriptKind.TS;
  return ts.createSourceFile(fileName, source, ts.ScriptTarget.Latest, true, kind);
}

/** Every descendant of a node, depth first, the node itself excluded. */
function descendants(root: ts.Node): ts.Node[] {
  const out: ts.Node[] = [];
  const visit = (n: ts.Node): void => {
    out.push(n);
    ts.forEachChild(n, visit);
  };
  ts.forEachChild(root, visit);
  return out;
}

/**
 * What each `createApiKey` call passes as `organizationId`, as source text.
 *
 * A string literal comes back with its quotes, which is how cell 3 tells it from an identifier.
 * The AST reaches the property wherever it sits in the object literal, and a parenthesised or
 * multi-line value is one node like any other.
 *
 * @param {string} source - The source text to read.
 * @param {string} [fileName] - Parse name; only the extension matters.
 * @returns {string[]} One entry per call, in source order.
 */
function mintOrganisationArgs(source: string, fileName = 'x.tsx'): string[] {
  const sf = parse(source, fileName);
  const out: string[] = [];
  for (const n of descendants(sf)) {
    if (!ts.isCallExpression(n) || !ts.isIdentifier(n.expression) || n.expression.text !== 'createApiKey') continue;
    const arg = n.arguments[0];
    if (arg === undefined || !ts.isObjectLiteralExpression(arg)) {
      out.push('(no object literal)');
      continue;
    }
    const prop = arg.properties.find(
      (p) => ts.isPropertyAssignment(p) && ts.isIdentifier(p.name) && p.name.text === 'organizationId',
    );
    out.push(prop !== undefined && ts.isPropertyAssignment(prop) ? prop.initializer.getText(sf) : '(no organizationId key)');
  }
  return out;
}

/**
 * The argument list of every real `fetchApiKeys(...)` CALL, as source text.
 *
 * A call is a CallExpression whose callee is the identifier, so the function's own declaration is
 * not a call (it is a FunctionDeclaration) and a commented-out call is not a call (a comment is not
 * a node). KS-1589 N6b: the argument is whatever node sits there, parentheses included.
 *
 * @param {string} source - The source text to read.
 * @param {string} [fileName] - Parse name; only the extension matters.
 * @returns {string[]} One entry per call: its arguments joined with ', '.
 */
function fetchApiKeysArgs(source: string, fileName = 'x.tsx'): string[] {
  const sf = parse(source, fileName);
  const out: string[] = [];
  for (const n of descendants(sf)) {
    if (ts.isCallExpression(n) && ts.isIdentifier(n.expression) && n.expression.text === 'fetchApiKeys') {
      out.push(n.arguments.map((a) => a.getText(sf)).join(', '));
    }
  }
  return out;
}

/**
 * Every place `fetchApiKeys` is taken as a VALUE rather than called.
 *
 * KS-1589 N7: `const f = fetchApiKeys; f('x')` defeats cell 4 by moving the call site to a name the
 * guard does not know. Importing it by name, re-exporting it and declaring it are not escapes, and
 * someone else's `.fetchApiKeys` property is not this function, so those four are excluded. Nor is
 * a SAME-NAME destructure (`const { fetchApiKeys } = api`): the call site keeps the name, so cell 4
 * still reads it. A RENAMING destructure (`const { fetchApiKeys: f } = api`) is an escape like any
 * other, and is the shape that exclusion must not swallow.
 *
 * @param {string} source - The source text to read.
 * @param {string} [fileName] - Parse name; only the extension matters.
 * @returns {string[]} One description per escape, naming the syntax that holds it.
 */
function fetchApiKeysValueUses(source: string, fileName = 'x.tsx'): string[] {
  const sf = parse(source, fileName);
  const out: string[] = [];
  for (const n of descendants(sf)) {
    if (!ts.isIdentifier(n) || n.text !== 'fetchApiKeys') continue;
    const p: ts.Node | undefined = n.parent;
    if (p === undefined) continue;
    if (ts.isCallExpression(p) && p.expression === n) continue;
    if (ts.isFunctionDeclaration(p) && p.name === n) continue;
    if (ts.isImportSpecifier(p) || ts.isExportSpecifier(p)) continue;
    if (ts.isPropertyAccessExpression(p) && p.name === n) continue;
    if (ts.isBindingElement(p) && p.name === n && p.propertyName === undefined) continue;
    out.push(`taken as a value in ${ts.SyntaxKind[p.kind]}`);
  }
  return out;
}

/** What a latest-request-wins loader looks like in the source. */
interface RaceWiring {
  /** The loader was located at all. A missing loader is a guard that is pinning nothing. */
  found: boolean;
  /** A sequence number is taken, then awaited, then compared before the first state write. */
  guarded: boolean;
}

/**
 * Whether a `useCallback` loader is wired latest-request-wins.
 *
 * The order is the whole claim: take a sequence number, await, compare, and only then write state.
 * Positions come from the AST, so a commented-out comparison is absent (KS-1589 N3) and a
 * comparison moved after the first write, or before the await, does not count.
 *
 * @param {string} source - The page source.
 * @param {string} fileName - Parse name; only the extension matters.
 * @param {string} loader - The `const <loader> = useCallback(async () => …)` to read.
 * @param {string} seqRef - The ref holding the sequence number, without `.current`.
 * @returns {RaceWiring} Whether it was found, and whether it is guarded.
 */
function latestRequestWins(source: string, fileName: string, loader: string, seqRef: string): RaceWiring {
  const sf = parse(source, fileName);
  let body: ts.Node | undefined;
  for (const n of descendants(sf)) {
    if (!ts.isVariableDeclaration(n) || !ts.isIdentifier(n.name) || n.name.text !== loader) continue;
    const init = n.initializer;
    if (init === undefined || !ts.isCallExpression(init)) continue;
    if (!ts.isIdentifier(init.expression) || init.expression.text !== 'useCallback') continue;
    const fn = init.arguments[0];
    if (fn !== undefined && (ts.isArrowFunction(fn) || ts.isFunctionExpression(fn))) body = fn.body;
  }
  if (body === undefined) return { found: false, guarded: false };

  const inner = descendants(body);
  const at = (n: ts.Node): number => n.getStart(sf);
  const first = (xs: number[]): number => (xs.length === 0 ? Number.POSITIVE_INFINITY : Math.min(...xs));

  const takes = inner
    .filter((n) => ts.isPrefixUnaryExpression(n) && n.operator === ts.SyntaxKind.PlusPlusToken && n.operand.getText(sf) === `${seqRef}.current`)
    .map(at);
  const awaits = inner.filter((n) => ts.isAwaitExpression(n)).map(at);
  const guards = inner
    .filter((n) => {
      if (!ts.isIfStatement(n)) return false;
      const c = n.expression;
      if (!ts.isBinaryExpression(c) || c.operatorToken.kind !== ts.SyntaxKind.ExclamationEqualsEqualsToken) return false;
      if (c.right.getText(sf) !== `${seqRef}.current`) return false;
      const t = n.thenStatement;
      return ts.isReturnStatement(t) || (ts.isBlock(t) && t.statements.length === 1 && ts.isReturnStatement(t.statements[0]));
    })
    .map(at);
  const writes = inner
    .filter((n) => ts.isCallExpression(n) && ts.isIdentifier(n.expression) && /^set[A-Z]/.test(n.expression.text))
    .map(at);

  const take = first(takes);
  if (!Number.isFinite(take)) return { found: true, guarded: false };
  const wait = first(awaits.filter((a) => a > take));
  if (!Number.isFinite(wait)) return { found: true, guarded: false };
  const guard = first(guards.filter((g) => g > wait));
  if (!Number.isFinite(guard)) return { found: true, guarded: false };
  const write = first(writes.filter((w) => w > wait));
  // No state write after the await means nothing stale can be published.
  return { found: true, guarded: !Number.isFinite(write) || guard < write };
}

/** What a synchronous in-flight guard looks like in the source. */
interface InFlightGuard {
  /** The handler was located at all. */
  found: boolean;
  /** It returns early on the ref before doing any awaiting. */
  checksBeforeAwait: boolean;
  /** It raises the ref before the await, so a second click within the same tick is refused. */
  setsBeforeAwait: boolean;
  /** It lowers the ref after the await, so a later click is allowed. */
  clearsAfterAwait: boolean;
}

/**
 * Whether a handler is guarded against a double submit by a synchronous ref.
 *
 * React state lags a fast double click, so the page uses a ref. The claim is again an order: check
 * and raise before the await, lower after it. KS-1589 N10 deleted all three and nothing noticed.
 *
 * @param {string} source - The page source.
 * @param {string} fileName - Parse name; only the extension matters.
 * @param {string} handler - The `const <handler> = async () => …` to read.
 * @param {string} ref - The in-flight ref, without `.current`.
 * @returns {InFlightGuard} Each half of the wiring, separately.
 */
function inFlightGuard(source: string, fileName: string, handler: string, ref: string): InFlightGuard {
  const sf = parse(source, fileName);
  const miss: InFlightGuard = { found: false, checksBeforeAwait: false, setsBeforeAwait: false, clearsAfterAwait: false };
  let body: ts.Node | undefined;
  for (const n of descendants(sf)) {
    if (!ts.isVariableDeclaration(n) || !ts.isIdentifier(n.name) || n.name.text !== handler) continue;
    const init = n.initializer;
    if (init !== undefined && (ts.isArrowFunction(init) || ts.isFunctionExpression(init))) body = init.body;
  }
  if (body === undefined) return miss;

  const inner = descendants(body);
  const at = (n: ts.Node): number => n.getStart(sf);
  const first = (xs: number[]): number => (xs.length === 0 ? Number.POSITIVE_INFINITY : Math.min(...xs));
  const cur = `${ref}.current`;

  const wait = first(inner.filter((n) => ts.isAwaitExpression(n)).map(at));
  const checks = inner
    .filter((n) => ts.isIfStatement(n) && descendants(n.expression).concat(n.expression).some((e) => e.getText(sf) === cur))
    .filter((n) => {
      const t = (n as ts.IfStatement).thenStatement;
      return ts.isReturnStatement(t) || (ts.isBlock(t) && t.statements.some((s) => ts.isReturnStatement(s)));
    })
    .map(at);
  const assigns = (literal: ts.SyntaxKind): number[] =>
    inner
      .filter(
        (n) =>
          ts.isBinaryExpression(n) &&
          n.operatorToken.kind === ts.SyntaxKind.EqualsToken &&
          n.left.getText(sf) === cur &&
          n.right.kind === literal,
      )
      .map(at);

  return {
    found: true,
    checksBeforeAwait: first(checks) < wait,
    setsBeforeAwait: first(assigns(ts.SyntaxKind.TrueKeyword)) < wait,
    clearsAfterAwait: assigns(ts.SyntaxKind.FalseKeyword).some((p) => p > wait),
  };
}

const PLAIN_IDENTIFIER = /^[A-Za-z_$][\w$.]*$/;

describe('KS-1564 — the API Keys page sends no invented organisation id', () => {
  it('the admin source tree exists (the guard is looking at something)', () => {
    expect(existsSync(API_TS)).toBe(true);
    expect(existsSync(PAGE_TSX)).toBe(true);
    expect(walk(ADMIN_SRC).length).toBeGreaterThan(20);
  });

  it('0b. with no harness override, the tree read is the one in this checkout', () => {
    // KS-1589: the override exists so a mutant can be shown to red a cell without touching the
    // product file. If it ever became the default, every cell below would be pinning a copy.
    if (process.env.KS1564_ADMIN_SRC === undefined) {
      expect(ADMIN_SRC).toBe(join(DEV_ROOT, 'frontend', 'admin', 'src'));
    } else {
      expect(ADMIN_SRC).toBe(process.env.KS1564_ADMIN_SRC);
    }
  });

  it('1. the retired placeholder id appears nowhere under frontend/admin/src', () => {
    expect(filesContaining(PLACEHOLDER)).toEqual([]);
  });

  it('2. fetchApiKeys takes a REQUIRED organisation id: no optional marker and no fallback', () => {
    const api = readFileSync(API_TS, 'utf8');
    expect(api).toMatch(/export async function fetchApiKeys\(\s*organizationId: string\s*\)/);
    expect(api).not.toMatch(/organizationId\s*\|\|/);
  });

  it('3. the createApiKey call site passes an identifier, never a string literal', () => {
    const args = mintOrganisationArgs(readFileSync(PAGE_TSX, 'utf8'), 'ApiKeys.tsx');
    expect(args).toHaveLength(1);
    expect(args[0]).toMatch(PLAIN_IDENTIFIER);
  });

  it('4. every fetchApiKeys CALL passes a plain identifier, and the name is never taken as a value', () => {
    const files = walk(ADMIN_SRC);
    const calls = files.flatMap((f) => fetchApiKeysArgs(readFileSync(f, 'utf8'), f));
    expect(calls.length).toBeGreaterThan(0);
    for (const arg of calls) expect(arg, `argument ${JSON.stringify(arg)}`).toMatch(PLAIN_IDENTIFIER);
    // KS-1589 N7. Without this half, an alias moves every call site to a name cell 4 cannot see,
    // and the loop above passes on the one remaining honest call.
    const escapes = files.flatMap((f) => fetchApiKeysValueUses(readFileSync(f, 'utf8'), f).map((e) => `${relative(DEV_ROOT, f)}: ${e}`));
    expect(escapes).toEqual([]);
  });

  it('5. loadKeys is latest-request-wins: a sequence number is taken, then awaited, then compared before the first state write', () => {
    const wiring = latestRequestWins(readFileSync(PAGE_TSX, 'utf8'), 'ApiKeys.tsx', 'loadKeys', 'keysReqRef');
    expect(wiring.found, 'loadKeys was not found at all').toBe(true);
    expect(wiring.guarded).toBe(true);
  });

  it('6. loadOrganizations is latest-request-wins too (a tenant switch races the same way)', () => {
    // KS-1589 N9: deleting this guard reded nothing. The gate noted that even its browser run does
    // not exercise the line, because the real route remounts the component - so the source is the
    // only place it is pinned at all.
    const wiring = latestRequestWins(readFileSync(PAGE_TSX, 'utf8'), 'ApiKeys.tsx', 'loadOrganizations', 'orgsReqRef');
    expect(wiring.found, 'loadOrganizations was not found at all').toBe(true);
    expect(wiring.guarded).toBe(true);
  });

  it('7. Generate is guarded against a double submit by a synchronous in-flight ref', () => {
    // KS-1589 N10: React state lags a fast double click, so the page uses a ref. All three parts
    // matter - check and raise before the await, lower after it.
    const guard = inFlightGuard(readFileSync(PAGE_TSX, 'utf8'), 'ApiKeys.tsx', 'handleGenerateKey', 'submitRef');
    expect(guard.found, 'handleGenerateKey was not found at all').toBe(true);
    expect(guard.checksBeforeAwait, 'no early return on the in-flight ref before the await').toBe(true);
    expect(guard.setsBeforeAwait, 'the in-flight ref is not raised before the await').toBe(true);
    expect(guard.clearsAfterAwait, 'the in-flight ref is never lowered after the await').toBe(true);
  });

  // CONTROLS. Without these the cells above could pass against a guard that cannot see anything.
  it('C1. CONTROL — the walker finds a literal that IS in the tree', () => {
    expect(filesContaining('X-Tenant-Override')).toContain(relative(DEV_ROOT, API_TS));
  });

  it('C2. CONTROL — the extractor reports a planted literal, and an identifier for the real shape', () => {
    const planted = `await createApiKey({ name: 'x', organizationId: '${PLACEHOLDER}', scopes: [] })`;
    expect(mintOrganisationArgs(planted)).toEqual([`'${PLACEHOLDER}'`]);
    expect(mintOrganisationArgs(planted)[0]).not.toMatch(PLAIN_IDENTIFIER);
    const real = `await createApiKey({ name: x, organizationId: dialogOrgId, scopes: [] })`;
    expect(mintOrganisationArgs(real)).toEqual(['dialogOrgId']);
  });

  it('C3. CONTROL — the argument checker, the alias checker and the race-wiring checker REFUSE planted bad shapes', () => {
    const bad = [
      `fetchApiKeys(orgId || '${PLACEHOLDER}')`,
      `fetchApiKeys(orgId ?? 'x')`,
      `fetchApiKeys('x')`,
      'fetchApiKeys(`${a}`)',
      `fetchApiKeys(a ? b : c)`,
      // KS-1589 N6b - the shape the old `[^()]*` argument pattern could not match at all.
      `fetchApiKeys(String(orgId) || ['default','org'].join('-'))`,
    ];
    for (const src of bad) {
      const args = fetchApiKeysArgs(src);
      expect(args, `shape ${src}`).toHaveLength(1);
      expect(args[0], `shape ${src}`).not.toMatch(PLAIN_IDENTIFIER);
    }
    expect(fetchApiKeysArgs('const r = await fetchApiKeys(orgId);')).toEqual(['orgId']);
    expect(fetchApiKeysArgs('export async function fetchApiKeys(organizationId: string) { return 1; }')).toEqual([]);

    // KS-1589 N7 - the alias, and the three shapes that are NOT escapes.
    expect(fetchApiKeysValueUses(`const f = fetchApiKeys; void f('x');`)).toHaveLength(1);
    expect(fetchApiKeysValueUses(`const r = await fetchApiKeys(orgId);`)).toEqual([]);
    expect(fetchApiKeysValueUses(`import { fetchApiKeys } from '../services/api';`)).toEqual([]);
    expect(fetchApiKeysValueUses('export async function fetchApiKeys(organizationId: string) { return 1; }', 'api.ts')).toEqual([]);
    expect(fetchApiKeysValueUses(`void other.fetchApiKeys;`)).toEqual([]);
    expect(fetchApiKeysValueUses(`const { fetchApiKeys } = api; void fetchApiKeys(orgId);`)).toEqual([]);
    expect(fetchApiKeysValueUses(`const { fetchApiKeys: f } = api; void f('x');`)).toHaveLength(1);

    const wrap = (inner: string): string => `const loadKeys = useCallback(async () => {${inner}}, [orgId]);`;
    const good = wrap(`const seq = ++keysReqRef.current; const r = await fetchApiKeys(orgId); if (seq !== keysReqRef.current) return; setKeys([]);`);
    const noGuard = wrap(`const seq = ++keysReqRef.current; const r = await fetchApiKeys(orgId); setKeys([]);`);
    const lateGuard = wrap(`const seq = ++keysReqRef.current; const r = await fetchApiKeys(orgId); setKeys([]); if (seq !== keysReqRef.current) return;`);
    const noTake = wrap(`const r = await fetchApiKeys(orgId); if (seq !== keysReqRef.current) return; setKeys([]);`);
    const earlyGuard = wrap(`const seq = ++keysReqRef.current; if (seq !== keysReqRef.current) return; const r = await fetchApiKeys(orgId); setKeys([]);`);
    expect(latestRequestWins(good, 'x.tsx', 'loadKeys', 'keysReqRef').guarded).toBe(true);
    expect(latestRequestWins(noGuard, 'x.tsx', 'loadKeys', 'keysReqRef').guarded).toBe(false);
    expect(latestRequestWins(lateGuard, 'x.tsx', 'loadKeys', 'keysReqRef').guarded).toBe(false);
    expect(latestRequestWins(noTake, 'x.tsx', 'loadKeys', 'keysReqRef').guarded).toBe(false);
    expect(latestRequestWins(earlyGuard, 'x.tsx', 'loadKeys', 'keysReqRef').guarded).toBe(false);
    // A loader that is not there is not a pass.
    expect(latestRequestWins(good, 'x.tsx', 'loadNothing', 'keysReqRef')).toEqual({ found: false, guarded: false });

    // KS-1589 N10 - the in-flight guard, and each half removed in turn.
    const gen = (inner: string): string => `const handleGenerateKey = async () => {${inner}};`;
    const okGen = gen(`if (!o || submitRef.current) return; submitRef.current = true; const r = await createApiKey({}); submitRef.current = false;`);
    const noCheck = gen(`if (!o) return; submitRef.current = true; const r = await createApiKey({}); submitRef.current = false;`);
    const noSet = gen(`if (!o || submitRef.current) return; const r = await createApiKey({}); submitRef.current = false;`);
    const noClear = gen(`if (!o || submitRef.current) return; submitRef.current = true; const r = await createApiKey({});`);
    expect(inFlightGuard(okGen, 'x.tsx', 'handleGenerateKey', 'submitRef')).toEqual({
      found: true, checksBeforeAwait: true, setsBeforeAwait: true, clearsAfterAwait: true,
    });
    expect(inFlightGuard(noCheck, 'x.tsx', 'handleGenerateKey', 'submitRef').checksBeforeAwait).toBe(false);
    expect(inFlightGuard(noSet, 'x.tsx', 'handleGenerateKey', 'submitRef').setsBeforeAwait).toBe(false);
    expect(inFlightGuard(noClear, 'x.tsx', 'handleGenerateKey', 'submitRef').clearsAfterAwait).toBe(false);
    expect(inFlightGuard(okGen, 'x.tsx', 'handleNothing', 'submitRef').found).toBe(false);
  });

  it('C4. CONTROL — a comment is not code: a quoted bad call is not a finding, and a commented-out guard is not a guard', () => {
    // The two halves of reading the AST instead of the text. KS-1589 N3 is the second half, and it
    // is the KS-1319 class; the first half is why N8 - a comment quoting `fetchApiKeys(orgId || 'x')`
    // - used to red cell 4 for nothing. Both are now decided by what parses as a node.
    expect(fetchApiKeysArgs(`// fetchApiKeys(orgId || 'x')\nconst r = await fetchApiKeys(orgId);`)).toEqual(['orgId']);
    expect(fetchApiKeysArgs(`/* fetchApiKeys('x') */\n`)).toEqual([]);
    expect(fetchApiKeysValueUses(`// const f = fetchApiKeys;\n`)).toEqual([]);

    const commentedOut = `const loadKeys = useCallback(async () => {
      const seq = ++keysReqRef.current;
      const r = await fetchApiKeys(orgId);
      // if (seq !== keysReqRef.current) return;
      setKeys([]);
    }, [orgId]);`;
    expect(latestRequestWins(commentedOut, 'x.tsx', 'loadKeys', 'keysReqRef').guarded).toBe(false);
  });
});

import { beforeAll, describe, expect, it } from 'vitest';
import { execFileSync } from 'node:child_process';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import {
  CONTACT_EMAIL,
  EXAMPLE_DOMAIN,
  FIXTURE_PERSON_VALUES,
  FX,
  MASKING_CONTRACT,
  MOCK_SIGNATURE_MARKER,
  mask,
} from '../openapi/examples';

/**
 * KS-256 — the published-example contract, and its deliberate duplicate.
 *
 * `scripts/spec-examples/check/contract.mjs` re-declares the category sets and
 * fixture values that live here. That duplication is intentional: the guard
 * must run with no build step and no workspace resolution, so it still works
 * when this package is broken — which is exactly when a bad example is most
 * likely to slip through.
 *
 * @stuart.jamieson, KS-256 2026-07-28: "A unit test asserting the two agree is
 * cheaper than the coupling." This is that test. If it fails, the guard and
 * the fixture set have drifted and one of them is now wrong.
 */

/** Parse the guard's duplicated contract without importing it as a module. */
function readGuardContract(): string {
  const here = path.dirname(fileURLToPath(import.meta.url));
  const contractPath = path.resolve(here, '../../../../scripts/spec-examples/check/contract.mjs');
  return fs.readFileSync(contractPath, 'utf8');
}

/** Extract a `new Set([...])` literal's string members from the guard source. */
function guardSetMembers(source: string, constName: string): Set<string> {
  const match = source.match(new RegExp(`${constName}\\s*=\\s*new Set\\(\\[([\\s\\S]*?)\\]\\)`));
  if (!match) throw new Error(`${constName} not found in the guard contract`);
  return new Set([...match[1].matchAll(/'([^']*)'/g)].map((m) => m[1]));
}

describe('KS-256 — guard contract stays in step with the fixture set', () => {
  const source = readGuardContract();

  it('declares the same person-shaped fields (rule E5 / masking category 3)', () => {
    expect(guardSetMembers(source, 'PERSON_FIELDS')).toEqual(MASKING_CONTRACT.personFields);
  });

  it('declares the same infrastructure fields (rule E6 / masking category 4)', () => {
    expect(guardSetMembers(source, 'INFRA_FIELDS')).toEqual(MASKING_CONTRACT.infraFields);
  });

  it('accepts exactly the fixture person values the fixture set publishes', () => {
    expect(guardSetMembers(source, 'FIXTURE_PERSON_VALUES')).toEqual(new Set(FIXTURE_PERSON_VALUES));
  });

  it('allows exactly the one declared contact address, and no other domain', () => {
    expect(guardSetMembers(source, 'ALLOWED_EMAILS')).toEqual(new Set([CONTACT_EMAIL]));
    expect(guardSetMembers(source, 'ALLOWED_EMAIL_DOMAINS')).toEqual(new Set([EXAMPLE_DOMAIN]));
  });

  it('agrees on the inert JWT signature marker (rule E2)', () => {
    expect(source).toContain(`MOCK_SIGNATURE_MARKER = '${MOCK_SIGNATURE_MARKER}'`);
  });

  it('declares the same system-secret fields (masking category 2)', () => {
    expect(guardSetMembers(source, 'SYSTEM_SECRET_FIELDS')).toEqual(
      MASKING_CONTRACT.systemSecretFields,
    );
  });

  /**
   * Rule E8 accepts only ids it can name. Every FX id must therefore be in the
   * guard's list, or a legitimate example would go red — and, more importantly,
   * an id the guard does not know is one it cannot clear.
   */
  it('recognises every FX identifier (rule E8)', () => {
    const declared = guardSetMembers(source, 'FIXTURE_ID_VALUES');
    for (const id of [FX.tenant.id, FX.issuer.id, FX.holder.id, FX.document.id, FX.anchor.id]) {
      expect(declared).toContain(id);
    }
  });

  /**
   * The inverse, and the one that actually protects us: the guard must NOT
   * recognise a seeded account id. `a0000000-…-000000000010` is
   * `demo@secuura.io`'s, and it reached the published spec in four places
   * before E8 existed.
   */
  it('does not recognise any seeded account id (rule E8)', () => {
    const declared = guardSetMembers(source, 'FIXTURE_ID_VALUES');
    for (const id of declared) {
      expect(id.startsWith('a0000000-0000-4000-8000')).toBe(false);
    }
  });
});

describe('KS-256 — no fixture value identifies a live account', () => {
  /**
   * The seeded accounts. The published spec must never name one: it ships to
   * partner integrators, and `demo@secuura.io` is a real loginable
   * `ISSUER_ADMIN` (`services/auth/src/repositories/userRepo.ts:1001`).
   * Live values are supplied at run time by systemTest, which never ships.
   */
  const SEEDED_ACCOUNT_VALUES = [
    'demo@secuura.io', 'admin@secuura.com', 'issuer@secuura.com',
    'a0000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000010',
    'a0000000-0000-4000-8000-000000000020',
  ];

  it('uses no seeded account email or id', () => {
    const published = JSON.stringify(FX);
    for (const seeded of SEEDED_ACCOUNT_VALUES) {
      expect(published).not.toContain(seeded);
    }
  });

  it('puts every person-shaped address on the reserved example domain', () => {
    for (const value of FIXTURE_PERSON_VALUES) {
      if (value.includes('@')) expect(value.endsWith(`@${EXAMPLE_DOMAIN}`)).toBe(true);
    }
  });
});

describe('KS-256 — fixture ids match the format the API actually returns', () => {
  const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

  /**
   * `verify-spec-examples.mjs` observed 7 of 7 `data.user.id` values in real
   * 2xx login responses to be UUIDs. The previous ULID-ish literals
   * (`user_01HC9ZK1…`) published a format the API never emits.
   */
  it('gives tenant, issuer and holder UUID-shaped ids', () => {
    expect(FX.tenant.id).toMatch(UUID);
    expect(FX.issuer.id).toMatch(UUID);
    expect(FX.holder.id).toMatch(UUID);
  });

  /** `'ISSUER'` and `'HOLDER'` are not members of `UserRole`. */
  it('uses only valid UserRole values', () => {
    const USER_ROLES = ['OWNER', 'ISSUER_ADMIN', 'ISSUER_APPROVER', 'VERIFIER', 'ORG_ADMIN', 'SYSTEM_ADMIN'];
    expect(USER_ROLES).toContain(FX.issuer.role);
    expect(USER_ROLES).toContain(FX.holder.role);
  });

  /** KS-481: the seeded canonical document, epoch-0 so rule E4 cannot match. */
  it('keeps the canonical document id in the seeded, E4-safe form', () => {
    expect(FX.document.id).toBe('doc-0000000000000-5eeded0c');
  });

  /**
   * KS-679 — this cell is the one that was missing, which is why the published
   * `Anchor.id` could carry `anc_01HC9ZN4ANCHORFIXTURE1` for months: a format
   * the anchoring service has NEVER minted. It mints
   * `anchor_${randomUUID()}` (`services/anchoring/src/index.ts:473`, and the
   * batch path appends `_<i>` at :806), and the live `anchor_store` held zero
   * rows matching `anc\_%` against 61,507 matching `anchor\_%`.
   *
   * Sitting in FX made rule E8 *certify* the wrong value rather than catch it,
   * so nothing in the estate could have found this. Pinning the prefix and the
   * uuid separately means a future edit cannot reopen it by changing either
   * half — asserting the whole literal would pass equally for a value that is
   * merely unchanged, which is not the property this cell is for.
   */
  it('gives the anchor the `anchor_<uuid>` id the service actually mints', () => {
    const [prefix, ...rest] = FX.anchor.id.split('_');
    expect(prefix).toBe('anchor');
    expect(rest.join('_')).toMatch(UUID);
  });
});

describe('KS-256 — the guard actually fires (positive control)', () => {
  /**
   * A guard that never goes red is worse than no guard, because it is read as
   * evidence. This plants one violation per rule and asserts all seven fire.
   *
   * The fixture is BUILT AT RUN TIME into a temp file, never committed: a
   * checked-in spec full of leak-shaped literals is exactly what secret
   * scanning exists to catch, and it would be right to catch it. Each value
   * below is shaped to trip its rule without resembling a real provider key.
   */
  const LEAKY_SPEC = [
    'openapi: 3.0.3',
    'info:',
    '  title: KS-256 positive control',
    'paths:',
    '  /x:',
    '    get:',
    // E1 also fires here — descriptions leak as surely as examples do.
    "      description: 'Contact margaret.thatcher@realcompany.co.uk for access.'",
    '      responses:',
    "        '200':",
    '          content:',
    '            application/json:',
    '              example:',
    '                email: margaret.thatcher@realcompany.co.uk',   // E1 + E5
    '                firstName: Margaret',                          // E5
    '                accessToken: eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiJyZWFsIn0.n0tAMockSignature', // E2
    // E3 (seeded-credential vocabulary) AND E9 (a usable password — this is
    // a request example, so Schemathesis would execute it and register the
    // account). One value, two distinct failure modes.
    '                password: acme123',
    '                documentId: doc-1777346021120-1e528170',       // E4
    '                db_host: prod-pg-01.internal',                 // E6
    '                apiKey: QWxsWW91ckJhc2VBcmVCZWxvbmdUb1VzMDAwMTExMjIyMzMzNDQ0', // E7
    // E8 — the seeded id of demo@secuura.io, which reached the real spec.
    '                userId: a0000000-0000-4000-8000-000000000010',
  ].join('\n');

  const guardPath = path.resolve(
    path.dirname(fileURLToPath(import.meta.url)),
    '../../../../scripts/spec-examples/check-spec-examples.mjs',
  );

  /** @returns the guard's JSON report for a spec written to a temp file. */
  function runGuardOn(spec: string): { findings: { rule: string; value: string }[] } {
    const specPath = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'ks256-')), 'spec.yaml');
    fs.writeFileSync(specPath, spec);
    try {
      // The guard exits 1 on findings, so execFileSync throws; the report is
      // still on stdout, which is what we want to assert against.
      const stdout = execFileSync('node', [guardPath, '--spec', specPath, '--json'], {
        encoding: 'utf8',
      });
      return JSON.parse(stdout);
    } catch (err) {
      return JSON.parse((err as { stdout: string }).stdout);
    } finally {
      fs.rmSync(path.dirname(specPath), { recursive: true, force: true });
    }
  }

  it('fires every one of the nine rules on a planted leak', () => {
    const rules = new Set(runGuardOn(LEAKY_SPEC).findings.map((f) => f.rule));
    expect([...rules].sort()).toEqual(['E1', 'E2', 'E3', 'E4', 'E5', 'E6', 'E7', 'E8', 'E9']);
  });

  it('never echoes a suspected secret in full', () => {
    // A guard that prints the leak it just found is its own disclosure.
    for (const finding of runGuardOn(LEAKY_SPEC).findings) {
      expect(finding.value).not.toContain('n0tAMockSignature');
      expect(finding.value).not.toContain('QWxsWW91ckJhc2VBcmVCZWxvbmdUb1Vz');
    }
  });

  it('passes a spec whose only address is the declared contact', () => {
    const clean = ['openapi: 3.0.3', 'info:', '  contact:', `    email: ${CONTACT_EMAIL}`].join('\n');
    expect(runGuardOn(clean).findings).toHaveLength(0);
  });
});

describe('KS-677 — the name-keyed rules reach SCALAR examples', () => {
  /**
   * E5, E8 and E9 all key off a field NAME. An object-valued example supplies
   * one per recursion step, but a scalar example's path ends on the literal
   * `example`, so before KS-677 every one of them was tested as a field called
   * "example", matched nothing, and passed.
   *
   * The positive control above never caught this because it plants an OBJECT
   * example — the one shape that already worked. These cases plant the SAME
   * literal in the scalar positions the spec actually uses.
   */

  /** demo@secuura.io's seeded user id — E8's founding defect. */
  const SEEDED_ID = 'a0000000-0000-4000-8000-000000000010';

  const guardPath = path.resolve(
    path.dirname(fileURLToPath(import.meta.url)),
    '../../../../scripts/spec-examples/check-spec-examples.mjs',
  );

  /** @returns the guard's JSON report for a spec written to a temp file. */
  function runGuardOn(spec: string): { findings: { rule: string; field: string }[] } {
    const specPath = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'ks677-')), 'spec.yaml');
    fs.writeFileSync(specPath, spec);
    try {
      const stdout = execFileSync('node', [guardPath, '--spec', specPath, '--json'], {
        encoding: 'utf8',
      });
      return JSON.parse(stdout);
    } catch (err) {
      return JSON.parse((err as { stdout: string }).stdout);
    } finally {
      fs.rmSync(path.dirname(specPath), { recursive: true, force: true });
    }
  }

  /** A one-operation spec whose `userId` path parameter carries `example`. */
  function paramSpec(example: string): string {
    return [
      'openapi: 3.0.3',
      'info:',
      '  title: KS-677',
      'paths:',
      '  /users/{userId}:',
      '    get:',
      '      parameters:',
      '        - name: userId',
      '          in: path',
      '          required: true',
      ...example.split('\n'),
      '      responses:',
      "        '200':",
      '          description: ok',
    ].join('\n');
  }

  it('fires on a scalar example declared on the parameter SCHEMA', () => {
    // The shape the generated spec actually publishes.
    const findings = runGuardOn(
      paramSpec(['          schema:', '            type: string', `            example: ${SEEDED_ID}`].join('\n')),
    ).findings;
    expect(findings.map((f) => f.rule)).toContain('E8');
    // The finding must name the parameter, not the literal key `example`.
    expect(findings.find((f) => f.rule === 'E8')?.field).toBe('userId');
  });

  it('fires on a scalar example declared on the parameter itself', () => {
    // The other legal spelling; both must be covered.
    const findings = runGuardOn(
      paramSpec([`          example: ${SEEDED_ID}`, '          schema:', '            type: string'].join('\n')),
    ).findings;
    expect(findings.map((f) => f.rule)).toContain('E8');
  });

  it('fires on a scalar example declared on a schema PROPERTY', () => {
    const findings = runGuardOn(
      [
        'openapi: 3.0.3',
        'info:',
        '  title: KS-677',
        'components:',
        '  schemas:',
        '    User:',
        '      type: object',
        '      properties:',
        '        userId:',
        '          type: string',
        `          example: ${SEEDED_ID}`,
      ].join('\n'),
    ).findings;
    expect(findings.map((f) => f.rule)).toContain('E8');
    expect(findings.find((f) => f.rule === 'E8')?.field).toBe('userId');
  });

  it('still fires when the same literal is wrapped in an object example', () => {
    // The control: this position always worked, and must keep working.
    const findings = runGuardOn(
      paramSpec(
        ['          schema:', '            type: string', '            example:', `              userId: ${SEEDED_ID}`].join('\n'),
      ),
    ).findings;
    expect(findings.map((f) => f.rule)).toContain('E8');
  });

  it('does not invent findings on a clean scalar example', () => {
    // A fixture-set id in the same position must stay silent, or the rule is
    // just matching the position rather than the value.
    const findings = runGuardOn(
      paramSpec(['          schema:', '            type: string', `            example: ${FX.holder.id}`].join('\n')),
    ).findings;
    expect(findings).toHaveLength(0);
  });
});

describe('KS-679 — the E7 benign-shape widening is pinned (the seven-case control)', () => {
  /**
   * `BENIGN_SHAPES` is read only by `rules-example.mjs`; nothing under
   * `packages/shared` imported it, so the KS-679 `<prefix>_<uuid>` entry had no
   * cell that would notice the anchor being dropped, the regex being loosened,
   * or the entry being narrowed back. These cells drive the GUARD itself (its
   * `--json` report) on a one-field spec built at run time — the same harness
   * as the positive control above — so a change to the list is seen where it
   * acts, not where it is declared.
   *
   * The four dangerous values are ASSEMBLED at run time from fragments, and
   * each provider's fixed-length run is broken with a `-`, so no committed
   * literal matches a real key pattern (the GitHub PAT, Stripe live-key and
   * AWS access-key prefixes each followed by their fixed-length alphanumeric
   * run): secret scanning would be right to flag one that did. E7 does
   * not care — it reads only "≥ 40 unbroken `[A-Za-z0-9+/=_-]` chars and no
   * benign shape", and `-` is inside that class.
   */
  const guardPath = path.resolve(
    path.dirname(fileURLToPath(import.meta.url)),
    '../../../../scripts/spec-examples/check-spec-examples.mjs',
  );

  /** @returns the guard's JSON report for a spec written to a temp file. */
  function runGuardOn(spec: string): { findings: { rule: string; field: string; value: string }[] } {
    const specPath = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'ks679-')), 'spec.yaml');
    fs.writeFileSync(specPath, spec);
    try {
      const stdout = execFileSync('node', [guardPath, '--spec', specPath, '--json'], {
        encoding: 'utf8',
      });
      return JSON.parse(stdout);
    } catch (err) {
      return JSON.parse((err as { stdout: string }).stdout);
    } finally {
      fs.rmSync(path.dirname(specPath), { recursive: true, force: true });
    }
  }

  /**
   * One operation, one OBJECT example, one field. Object position rather than
   * a scalar `example:` because E7 is value-keyed and the object shape is the
   * one every rule already reaches (KS-677's lesson was about the name-keyed
   * rules and scalar positions; it does not apply here, but the object shape
   * costs nothing). `opaqueRef` is not a person, account or credential field
   * name, so only value-keyed rules can fire on it.
   */
  function specWith(value: string): string {
    return [
      'openapi: 3.0.3',
      'info:',
      '  title: KS-679 seven-case control',
      'paths:',
      '  /x:',
      '    get:',
      '      responses:',
      "        '200':",
      '          content:',
      '            application/json:',
      '              example:',
      `                opaqueRef: ${value}`,
    ].join('\n');
  }

  const rulesFor = (value: string): Set<string> =>
    new Set(runGuardOn(specWith(value)).findings.map((f) => f.rule));

  // The two benign rows: the new fixture, and a real request id of the same class.
  const NEW_FIXTURE = 'anchor_00000000-0000-4000-8000-000000000032';
  const REQUEST_ID = 'req_3f2b1c9e-7d4a-4b6c-8e1f-2a3b4c5d6e7f';

  // The four dangerous rows, built at run time — see the block comment above.
  const STRIPE_SHAPED = ['sk', 'live'].join('_') + '_' + '51H8xQ2eZ-' + 'k9Qw7Lm2Np4Rt6Vx8Yz0Bc1Df3Gh5Jk7';
  const GITHUB_PAT_SHAPED = ['gh', 'p_'].join('') + '16C7e42F292c-' + '6912E7710c838347Ae178B4a';
  const AWS_KEY_SHAPED = ['AK', 'IA'].join('') + 'IOSFODNN-' + '7EXAMPLE' + 'Q1W2E3R4T5Y6U7I8O9P0AbCdEfGh';
  const PREFIX_PLUS_JUNK = 'anchor_' + 'not-a-uuid-at-all-' + 'just-forty-plus-chars-of-junk';

  // A JWT: dots put it outside E7's character class, so E7 can never reach it
  // whatever its length — E2 is the rule that owns JWTs.
  const JWT = 'eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiJyZWFsIn0.n0tAMockSignature';

  it('the values are shaped for E7: every row but the JWT is ≥ 40 chars of the E7 class', () => {
    for (const v of [NEW_FIXTURE, REQUEST_ID, STRIPE_SHAPED, GITHUB_PAT_SHAPED, AWS_KEY_SHAPED, PREFIX_PLUS_JUNK]) {
      expect(v).toMatch(/^[A-Za-z0-9+/=_-]{40,}$/);
    }
    expect(JWT).not.toMatch(/^[A-Za-z0-9+/=_-]{40,}$/);
  });

  it('the new fixture `anchor_<uuid>` is BENIGN — E7 does not fire', () => {
    expect(rulesFor(NEW_FIXTURE).has('E7')).toBe(false);
  });

  it('a `req_<uuid>` request id — the same class — is BENIGN', () => {
    expect(rulesFor(REQUEST_ID).has('E7')).toBe(false);
  });

  it('a Stripe-shaped live key still fires E7', () => {
    expect(rulesFor(STRIPE_SHAPED).has('E7')).toBe(true);
  });

  it('a GitHub-PAT-shaped token still fires E7', () => {
    expect(rulesFor(GITHUB_PAT_SHAPED).has('E7')).toBe(true);
  });

  it('an AWS-key-shaped blob still fires E7', () => {
    expect(rulesFor(AWS_KEY_SHAPED).has('E7')).toBe(true);
  });

  it('a known prefix followed by junk that is not a uuid still fires E7 — the regex is anchored to an exact uuid', () => {
    expect(rulesFor(PREFIX_PLUS_JUNK).has('E7')).toBe(true);
  });

  it('a JWT is E2\'s, not E7\'s — the dots keep it out of E7\'s character class', () => {
    const rules = rulesFor(JWT);
    expect(rules.has('E2')).toBe(true);
    expect(rules.has('E7')).toBe(false);
  });

  /**
   * #922 tier-2 gate, F1: the exemption admits exactly the minted form. Each
   * row below sits on one boundary of `PREFIXED_UUID_RE` in contract.mjs. All
   * rows go through ONE guard run, one field each, so the list is still read
   * where it acts; the count cell proves the run was live, because a guard
   * that crashed would report nothing and every "does not fire" row would pass.
   * Every value is at least 40 chars. E7 returns before reading BENIGN_SHAPES
   * below that, so the shorter boundaries are pinned on the pattern itself.
   */
  const V4 = '3f2b1c9e-7d4a-4b6c-8e1f-2a3b4c5d6e7f';
  // [row, value, E7 fires]. Row ids are letters and digits: each names a field.
  const BOUNDARY_ROWS: ReadonlyArray<readonly [string, string, boolean]> = [
    ['len3', `req_${V4}`, false],
    ['len12', `abcdefghijkl_${V4}`, false],
    ['len13', `abcdefghijklm_${V4}`, true],
    ['len60', `${'x'.repeat(60)}_${V4}`, true],
    ['upperPrefix', `ANCHOR_${V4}`, true],
    ['upperHex', `anchor_${V4.toUpperCase()}`, true],
    ['uuidV1', 'anchor_3f2b1c9e-7d4a-1b6c-8e1f-2a3b4c5d6e7f', true],
    ['uuidNil', 'anchor_00000000-0000-0000-0000-000000000000', true],
    ['variant7', 'anchor_3f2b1c9e-7d4a-4b6c-7e1f-2a3b4c5d6e7f', true],
    // KS-1254: the variant nibble is lower-case only. Only the nibble differs from V4.
    ['variantLowerA', 'anchor_3f2b1c9e-7d4a-4b6c-ae1f-2a3b4c5d6e7f', false],
    ['variantUpperA', 'anchor_3f2b1c9e-7d4a-4b6c-Ae1f-2a3b4c5d6e7f', true],
    ['hexRun36', 'anchor_0123456789abcdef-0123456789abcdef-ab', true],
    ['noSeparator', `abcd${V4}`, true],
    ['twoSegments', `evt_test_${V4}`, true],
    ['digitPrefix', `k8s_${V4}`, true],
    ['trailingJunk', `req_${V4}SECRETSUFFIX`, true],
    ['batchForm', `anchor_${V4}_0`, true],
    // KS-1254: `cred` is refused as an exact prefix only (denycred below), so credit_ stays benign.
    ['credit', `credit_${V4}`, false],
  ];
  // Every secret-named prefix the pattern refuses that is long enough to reach E7.
  const SECRET_NAMED = [
    'token', 'secret', 'key', 'apikey', 'accesstoken', 'clientsecret', 'privatekey', 'password',
    'passwd', 'passphrase', 'pwd', 'credential', 'bearer', 'session', 'private', 'pat', 'auth',
    'cred', 'jwt', 'otp',
  ];
  const ROWS: ReadonlyArray<readonly [string, string, boolean]> = [
    ...BOUNDARY_ROWS,
    ...SECRET_NAMED.map((p) => [`deny${p}`, `${p}_${V4}`, true] as const),
  ];

  let firedE7: Map<string, number>;
  beforeAll(() => {
    const spec = [
      'openapi: 3.0.3',
      'info:',
      '  title: KS-679 F1 boundaries',
      'paths:',
      '  /x:',
      '    get:',
      '      responses:',
      "        '200':",
      '          content:',
      '            application/json:',
      '              example:',
      ...ROWS.map(([row, value]) => `                ref${row}: '${value}'`),
    ].join('\n');
    firedE7 = new Map();
    for (const f of runGuardOn(spec).findings) {
      if (f.rule === 'E7') firedE7.set(f.field, (firedE7.get(f.field) ?? 0) + 1);
    }
  });

  it('the boundary run is live: one E7 per firing row, on exactly those fields', () => {
    const expected = ROWS.filter(([, , fires]) => fires).map(([row]) => `ref${row}`);
    expect(expected.length).toBeGreaterThan(0);
    expect([...firedE7.keys()].sort()).toEqual([...expected].sort());
    expect([...firedE7.values()].every((n) => n === 1)).toBe(true);
  });

  it('the upper-case row really is upper-case (hex letters, not an all-digit uuid)', () => {
    expect(V4.toUpperCase()).not.toBe(V4);
  });

  it.each(ROWS)('%s', (row, value, fires) => {
    expect(value.length).toBeGreaterThanOrEqual(40);
    expect(firedE7.has(`ref${row}`)).toBe(fires);
  });

  describe('boundaries under E7\'s 40-char floor, pinned on the pattern', () => {
    let contract: { PREFIXED_UUID_RE: RegExp; BENIGN_SHAPES: RegExp[] };
    beforeAll(async () => {
      const contractPath = path.resolve(
        path.dirname(fileURLToPath(import.meta.url)),
        '../../../../scripts/spec-examples/check/contract.mjs',
      );
      contract = (await import(pathToFileURL(contractPath).href)) as typeof contract;
    });

    it('is the pattern the guard reads: a member of BENIGN_SHAPES', () => {
      expect(contract.BENIGN_SHAPES).toContain(contract.PREFIXED_UUID_RE);
    });

    it.each([
      ['ts', true],
      ['ce', true],
      ['a', false],
      ['sk', false],
      ['pk', false],
    ] as const)('prefix %s', (prefix, admitted) => {
      expect(`${prefix}_${V4}`.length).toBeLessThan(40);
      expect(contract.PREFIXED_UUID_RE.test(`${prefix}_${V4}`)).toBe(admitted);
    });

    it('admits 13 of the 14 minted prefixes and refuses key_ by design', () => {
      // The census in contract.mjs: every prefix a code site mints with a uuid.
      const minted = ['anchor', 'audit', 'batch', 'ce', 'conn', 'did', 'event', 'evt', 'int', 'key',
        'req', 'site', 'sync', 'ts'];
      const refused = minted.filter((p) => !contract.PREFIXED_UUID_RE.test(`${p}_${V4}`));
      expect(refused).toEqual(['key']);
    });
  });
});

describe('KS-256 — mask() renders each category correctly', () => {
  it('renders caller-supplied secrets as <your-…>, kebab-cased from the field', () => {
    expect(mask('password')).toBe('<your-password>');
    expect(mask('oldPassword')).toBe('<your-old-password>');
  });

  it('renders token-shaped system secrets as the inert JWT', () => {
    expect(mask('accessToken')?.endsWith(MOCK_SIGNATURE_MARKER)).toBe(true);
  });

  it('renders other system secrets as a named placeholder, never <your-…>', () => {
    // The caller cannot invent a client secret, so "your" would misinstruct.
    expect(mask('clientSecret')).toBe('<clientSecret>');
  });

  it('resolves person-shaped fields to the fixture set', () => {
    expect(mask('email')).toBe(FX.issuer.email);
    expect(mask('firstName')).toBe(FX.issuer.firstName);
    expect(mask('ipAddress')).toBe(FX.ipAddress);
  });

  it('refuses to example an infrastructure field rather than returning undefined', () => {
    expect(() => mask('db_host')).toThrow(/infrastructure field/);
  });

  it('leaves unobligated fields to the synthesiser', () => {
    expect(mask('title')).toBeUndefined();
  });
});
